package cn.sixnine.filmlog;

import android.appwidget.AppWidgetManager;
import android.content.Intent;
import android.os.Bundle;
import android.view.*;
import android.widget.*;

public final class WidgetConfigureActivity extends WorkspaceActivity {
    private int widgetId;private String selected="",selectedStyle=ExposureWidget.CLASSIC;private LinearLayout cards;private Button add;
    @Override public void onCreate(Bundle saved){super.onCreate(saved);setResult(RESULT_CANCELED);widgetId=getIntent().getIntExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,AppWidgetManager.INVALID_APPWIDGET_ID);if(widgetId==AppWidgetManager.INVALID_APPWIDGET_ID||!ExposureWidget.owned(this,widgetId)){finish();return;}selected=saved==null?ExposureWidget.target(this,widgetId):saved.getString("selected","");selectedStyle=saved==null?ExposureWidget.style(this,widgetId):saved.getString("style",ExposureWidget.CLASSIC);
        LinearLayout root=LibraryUi.column(this);root.setBackgroundColor(getColor(R.color.ui_background));setContentView(root);root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i;});root.requestApplyInsets();root.addView(LibraryUi.header(this,"桌面快捷记录",this::finish,null));
        ScrollView scroll=new ScrollView(this);LinearLayout content=LibraryUi.column(this);int p=LibraryUi.dp(this,20);content.setPadding(p,p,p,p);scroll.addView(content);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));TextView styleHeading=LibraryUi.text(this,"组件样式",18,getColor(R.color.ui_ink));content.addView(styleHeading);RadioGroup styles=new RadioGroup(this);styles.setOrientation(RadioGroup.VERTICAL);String[] names={"经典胶片 · B 版","雾面柔光"};String[] values={ExposureWidget.CLASSIC,ExposureWidget.FROST};for(int n=0;n<names.length;n++){RadioButton option=new RadioButton(this);option.setId(View.generateViewId());option.setTag(values[n]);option.setText(names[n]);option.setTextColor(getColor(R.color.ui_ink));option.setTextSize(16);option.setMinHeight(LibraryUi.dp(this,48));styles.addView(option,new RadioGroup.LayoutParams(-1,-2));option.setChecked(values[n].equals(selectedStyle));}styles.setOnCheckedChangeListener((group,checked)->{View option=group.findViewById(checked);if(option!=null)selectedStyle=String.valueOf(option.getTag());});content.addView(styles);TextView styleHint=LibraryUi.text(this,"每个组件可独立选择样式，之后可长按桌面组件重新设置。",13,getColor(R.color.ui_muted));styleHint.setPadding(0,LibraryUi.dp(this,4),0,p);content.addView(styleHint);TextView note=LibraryUi.text(this,"选择要放在桌面的胶卷",22,getColor(R.color.ui_ink));content.addView(note);TextView hint=LibraryUi.text(this,"选择样式和胶卷，再保存到桌面。点击封面查看胶卷；点击记录打开草稿，需在应用内保存。",13,getColor(R.color.ui_muted));hint.setPadding(0,p/2,0,p);content.addView(hint);cards=LibraryUi.column(this);content.addView(cards);
        LinearLayout footer=LibraryUi.column(this);footer.setPadding(p,LibraryUi.dp(this,8),p,p);add=LibraryUi.action(this,ExposureWidget.target(this,widgetId).isEmpty()?"添加到桌面":"保存组件",true,()->bind(selected));footer.addView(add);Button later=LibraryUi.action(this,"稍后选择胶卷",false,()->bind(""));LinearLayout.LayoutParams gap=new LinearLayout.LayoutParams(-1,-2);gap.topMargin=LibraryUi.dp(this,8);footer.addView(later,gap);root.addView(footer);renderCards();
    }
    private void renderCards(){cards.removeAllViews();boolean found=false;try(LogStore logs=new LogStore(this)){for(LogStore.Roll roll:logs.rolls())if(ExposureWidget.available(roll)){boolean checked=roll.id.equals(selected);found|=checked;View card=WidgetCard.choice(this,logs,roll,checked,()->{selected=roll.id;renderCards();});LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=LibraryUi.dp(this,12);cards.addView(card,p);}}if(cards.getChildCount()==0)cards.addView(LibraryUi.text(this,"暂无拍摄中的胶卷，请先在应用内装卷。",15,getColor(R.color.ui_muted)));add.setEnabled(found);add.setAlpha(found?1f:.45f);}
    private void bind(String roll){try{ExposureWidget.bind(this,widgetId,roll,selectedStyle);setResult(RESULT_OK,new Intent().putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,widgetId));finish();}catch(Exception error){Toast.makeText(this,error.getMessage(),Toast.LENGTH_LONG).show();renderCards();}}
    @Override protected void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);state.putString("selected",selected);state.putString("style",selectedStyle);}
}
